#include <vector>
#include <algorithm>

class Solution {
public:
    long long minTotalCostToProcess(std::vector<int>& costs) {
        std::sort(costs.rbegin(), costs.rend());
        long long total = 0;
        for (size_t i = 0; i < costs.size(); ++i) {
            total += (long long)(i + 1) * costs[i];
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public long minTotalCostToProcess(int[] costs) {
        Arrays.sort(costs);
        long total = 0;
        int n = costs.length;
        for (int i = 0; i < n; i++) {
            total += (long)(i + 1) * costs[n - 1 - i];
        }
        return total;
    }
}

